IF( $Permission.Skip_Validations_Permission
,false
,IF(AND(OR(Trip_Status__c = 'Confirmed',
            Trip_Status__c = 'Cancelled'
        ),
        OR(ISCHANGED(Entry_Date__c),
            ISCHANGED(Entry_State__c),
            ISCHANGED(Exit_Date__c)
        )
    ),
     IF(AND( $Permission.TSEG_CRM_Manager = false,
             $Permission.TSEG_Premium_Guest_Services = false,
             $Permission.TSEG_Operation=false),
        TRUE,
        FALSE
    ),
    IF(AND(Trip_Status__c = 'Completed',
            OR(ISCHANGED(Entry_Date__c),
                ISCHANGED(Entry_State__c)
            )
        ),
        IF( $Permission.TSEG_CRM_Manager = false,
            TRUE,
            FALSE
        ),
        IF(AND(Trip_Status__c = 'Completed', ISCHANGED(Exit_Date__c)),
            IF(AND( $Permission.TSEG_CRM_Manager = false,
                    $Permission.TSEG_Premium_Guest_Services = false,
                    $Permission.TSEG_Operation=false
                ),
                TRUE,
                FALSE
            ),
            FALSE
        )
    )
)
)
